local function short(s, n)
    s = tostring(s or ""):gsub("[%z\1-\31]", " ")
    if #s <= n then
        return s
    end
    local p = n - 3
    -- Avoid cutting a UTF-8 continuation sequence at a byte boundary.
    while p > 0 and s:byte(p + 1) and s:byte(p + 1) >= 128 and s:byte(p + 1) < 192 do
        p = p - 1
    end
    return s:sub(1, p) .. "..."
end
