local function validIcon(value)
    if value == nil or type(value) == "string" then
        return value
    end
    assert(type(value) == "table" and #value > 0 and #value <= 64, "Custom icons require 1..64 line segments")
    local copy = {}
    for i, p in ipairs(value) do
        assert(type(p) == "table" and #p == 4, "Each icon segment requires four coordinates")
        copy[i] = {}
        for j = 1, 4 do
            assert(
                finite(p[j]) and math.abs(p[j]) <= 100,
                "Icon coordinates must be finite and within -100..100"
            )
            copy[i][j] = p[j]
        end
    end
    return copy
end
local function icon(id, name, px, py, c, opacity, z, angle, scale)
    local strokes = type(name) == "table" and name or paths[name] or paths.script
    local cs, sn = math.cos(angle or 0), math.sin(angle or 0)
    scale = scale or 1
    for i, p in ipairs(strokes) do
        local ax, ay, bx, by =
            (p[1] - 10) * scale, (p[2] - 10) * scale, (p[3] - 10) * scale, (p[4] - 10) * scale
        line(
            id .. i,
            px + 10 + ax * cs - ay * sn,
            py + 10 + ax * sn + ay * cs,
            px + 10 + bx * cs - by * sn,
            py + 10 + bx * sn + by * cs,
            c,
            opacity,
            z
        )
    end
end
local function bitmap(id, bytes, px, py, w, h, opacity, r, z)
    if not bytes or imageErrors[id] then
        return false
    end
    local ok = pcall(function()
        local d = obj(id, "Image")
        d.Data = bytes
        d.Position = V(x + px * S, y + py * S)
        d.Size = V(w * S, h * S)
        d.Color = white
        d.Rounding = (r or 0) * S
        d.Transparency = clamp(a * opacity, 0, 1)
        d.ZIndex = z or 22
        d.Visible = a * opacity > 0.005
    end)
    if not ok then
        imageErrors[id] = true
        if pool[id] then
            pcall(function()
                pool[id].raw:Remove()
            end)
            pool[id] = nil
        end
    end
    return ok
end
local function asset(id)
    local record = assetData[id]
    if not record then
        return nil
    end
    local index = 1
    if app.AnimatedMedia and not app.ReducedMotion and app.Quality ~= "Low" and active then
        local position = motionClock % record.Duration
        for i, entry in ipairs(record.Frames) do
            position = position - entry.Duration
            if position < 0 then
                index = i
                break
            end
        end
    end
    local key = id .. ":" .. index
    if characterBytes[key] then
        return characterBytes[key]
    end
    if app.AssetStatus[key] == "failed" then
        return nil
    end
    local ok, bytes = pcall(function()
        assert(type(base64decode) == "function", "base64decode unavailable")
        return base64decode(record.Frames[index].Data)
    end)
    if ok and type(bytes) == "string" and bytes:sub(1, 8) == "\137PNG\13\10\26\10" then
        characterBytes[key] = bytes
        app.AssetStatus[id] = "ready"
        return bytes
    end
    app.AssetStatus[id] = "failed"
    app.AssetStatus[key] = "failed"
    return nil
end
local function hit(px, py, w, h, modal)
    return active
        and app.Visible
        and a > 0.9
        and (modal or (not popup and not capture and not confirm))
        and mx >= x + px * S
        and mx <= x + (px + w) * S
        and my >= y + py * S
        and my <= y + (py + h) * S
end
local function fire(fn, ...)
    if type(fn) ~= "function" or not app.Alive then
        return
    end
    local args, n = { ... }, select("#", ...)
    task.spawn(function()
        if not app.Alive then
            return
        end
        local ok, err = pcall(function()
            fn(unpackArgs(args, 1, n))
        end)
        if not ok and app.Alive then
            app.LastError = tostring(err)
            app:Notify({ Title = "Callback failed", Content = tostring(err), Type = "error" })
        end
    end)
end
function app:Notify(options, message)
    if not self.Alive then
        return nil
    end
    if type(options) ~= "table" then
        options = { Title = options, Content = message }
    end
    local duration = tonumber(options.Duration)
    if not finite(duration) then
        duration = 4
    end
    local n = {
        id = uid(),
        title = short(options.Title or "Occult Research Club", 40),
        message = short(options.Content or "", 72),
        kind = options.Type or "info",
        duration = clamp(duration, 1, 20),
        time = tick(),
    }
    notices[#notices + 1] = n
    if #notices > 3 then
        local old = table.remove(notices, 1)
        animations[old.id] = nil
    end
    return n.id
end
function app:SetTheme(name)
    local aliases = { purple = "Himejima", green = "Twilight", blue = "Obsidian", black = "Obsidian" }
    name = aliases[tostring(name):lower()] or name
    for i, t in ipairs(themes) do
        if t.Name:lower() == tostring(name):lower() then
            targetTheme = i
            self.Theme = t.Name
            return true
        end
    end
    return false, "Unknown theme"
end
function app:SetCharacter(id)
    for _, c in ipairs(characters) do
        if c.Id == id then
            self.Character = id
            self:SetTheme(c.Theme)
            animations.character = 0
            reactUntil = motionClock + 1
            return true
        end
    end
    return false, "Unknown character"
end
function app:SetAvatarData(bytes)
    assert(
        type(bytes) == "string" and #bytes > 0 and #bytes < 2000000,
        "Expected image bytes smaller than 2 MB"
    )
    avatarBytes = bytes
    self.AvatarStatus = "ready"
    imageErrors.avatar = nil
end
local function keyName(k)
    local names = {
        [0xA0] = "Left Shift",
        [0xA1] = "Right Shift",
        [0xA2] = "Left Ctrl",
        [0xA3] = "Right Ctrl",
        [0xA4] = "Left Alt",
        [0xA5] = "Right Alt",
        [0x2D] = "Insert",
        [0x24] = "Home",
        [0x23] = "End",
        [0x20] = "Space",
        [0x09] = "Tab",
        [0x0D] = "Enter",
        [0x2E] = "Delete",
    }
    if names[k] then
        return names[k]
    end
    if k >= 0x70 and k <= 0x87 then
        return "F" .. (k - 0x6F)
    end
    if k >= 0x30 and k <= 0x5A then
        return string.char(k)
    end
    return string.format("Key 0x%02X", k)
end
function app:SetKeybind(vk)
    assert(
        finite(vk) and vk >= 8 and vk <= 254 and vk == math.floor(vk) and vk ~= 27,
        "Use a VK key code (8..254), except Escape"
    )
    self.Keybind = vk
    previousKey = iskeypressed(vk)
    return true
end
function app:Show()
    if self.Alive then
        self.Visible = true
    end
end
function app:Hide()
    self.Visible = false
    popup = nil
    capture = nil
    confirm = nil
    drag = nil
    slide = nil
end
function app:Destroy()
    if not self.Alive then
        return
    end
    self.Alive = false
    if connection then
        connection:Disconnect()
        connection = nil
    end
    if self._DestroyAudio then
        self:_DestroyAudio()
    end
    for _, e in pairs(pool) do
        pcall(function()
            e.raw:Remove()
        end)
    end
    pool = {}
    animations = {}
    notices = {}
    characterBytes = {}
    focusItems = {}
    previousFocus = {}
    actionQueue = {}
    popup = nil
    capture = nil
    confirm = nil
    slide = nil
    drag = nil
    for _, tab in ipairs(self.Tabs) do
        for _, c in ipairs(tab.Controls) do
            c.Callback = nil
        end
    end
    if env.DxD == self then
        env.DxD = nil
    end
    if env.Rem == self then
        env.Rem = nil
    end
end
local Tab = {}
Tab.__index = Tab
local Control = {}
Control.__index = Control
function Control:GetValue()
    return self.Value
end
function Control:SetValue(value, silent)
    assert(app.Alive, "DxD has been destroyed")
    if self.Kind == "toggle" then
        value = not not value
    elseif self.Kind == "slider" then
        assert(finite(value), "Slider value must be a finite number")
        value = clamp(value, self.Min, self.Max)
        value = self.Min + math.floor((value - self.Min) / self.Step + 0.5) * self.Step
        value = clamp(value, self.Min, self.Max)
    elseif self.Kind == "dropdown" then
        local found = false
        for _, item in ipairs(self.Options) do
            if item == value then
                found = true
                break
            end
        end
        assert(found, "Dropdown value must be one of its Options")
    end
    local changed = self.Value ~= value
    self.Value = value
    if changed and not silent then
        fire(self.Callback, value)
    end
    return self
end
function Tab:_add(kind, o)
    assert(app.Alive, "DxD has been destroyed")
    o = o or {}
    assert(type(o) == "table", "Control options must be a table")
    assert(o.Callback == nil or type(o.Callback) == "function", "Callback must be a function")
    local c = setmetatable({
        Id = uid(),
        Kind = kind,
        Title = short(o.Title or kind, 80),
        Description = short(o.Description or "", 160),
        Callback = o.Callback,
        Disabled = o.Disabled == true,
    }, Control)
    c.Icon = validIcon(o.Icon)
        or ({
            button = "bolt",
            toggle = "power",
            slider = "sliders",
            dropdown = "layers",
            keybind = "key",
            label = "spark",
        })[kind]
    c.ButtonText = short(o.ButtonText or "Run", 18)
    c.Min = o.Min or 0
    c.Max = o.Max or 100
    c.Step = o.Step or 1
    if kind == "slider" then
        assert(
            finite(c.Min) and finite(c.Max) and finite(c.Step) and c.Max > c.Min and c.Step > 0,
            "Slider requires finite Max > Min and Step > 0"
        )
    end
    c.Options = {}
    if kind == "dropdown" then
        assert(
            type(o.Options) == "table" and #o.Options > 0 and #o.Options <= 128,
            "Dropdown requires 1..128 Options"
        )
        for i, v in ipairs(o.Options) do
            assert(type(v) == "string", "Dropdown Options must be strings")
            c.Options[i] = v
        end
    end
    c.Value = o.Default
    if kind == "toggle" then
        c.Value = not not o.Default
    elseif kind == "slider" then
        c:SetValue(o.Default or c.Min, true)
    elseif kind == "dropdown" then
        c:SetValue(o.Default or c.Options[1], true)
    end
    animations[c.Id .. "appear"] = 0
    self.Controls[#self.Controls + 1] = c
    return c
end
function Tab:AddButton(o)
    return self:_add("button", o)
end
function Tab:AddToggle(o)
    return self:_add("toggle", o)
end
function Tab:AddSlider(o)
    return self:_add("slider", o)
end
function Tab:AddDropdown(o)
    return self:_add("dropdown", o)
end
function Tab:AddLabel(o)
    if type(o) == "string" then
        o = { Title = o }
    end
    return self:_add("label", o)
end
local function replayTab(tab)
    animations.content = 0
    contentA = 0
    visitTime = motionClock
    popup = nil
    slide = nil
    capture = nil
    focusId = nil
    for _, c in ipairs(tab.Controls) do
        animations[c.Id .. "appear"] = 0
    end
end
function Tab:Select()
    assert(app.Alive, "DxD has been destroyed")
    if selected ~= self then
        selected = self
        replayTab(self)
    end
    for i, t in ipairs(app.Tabs) do
        if t == self then
            tabOffset = math.max(0, i - 5)
        end
    end
    return self
end
function app:AddTab(o)
    assert(self.Alive, "DxD has been destroyed")
    if type(o) == "string" then
        o = { Title = o }
    end
    o = o or {}
    assert(type(o) == "table", "Tab options must be a table")
    local tab = setmetatable({
        Id = uid(),
        Title = short(o.Title or "Tab", 32),
        Subtitle = short(o.Subtitle or "Your controls, beautifully in place.", 90),
        Icon = validIcon(o.Icon) or "script",
        Controls = {},
        Page = 1,
    }, Tab)
    self.Tabs[#self.Tabs + 1] = tab
    if not selected then
        selected = tab
    end
    return tab
end
function app:Confirm(options)
    assert(type(options) == "table" and type(options.Callback) == "function", "Confirm requires a Callback")
    confirm = {
        Title = short(options.Title or "Are you sure?", 50),
        Content = short(options.Content or "", 95),
        Callback = options.Callback,
    }
    focusId = nil
    popup = nil
end
local function interactive(id, px, py, w, h, fn, adjust, modal, disabled)
    local allowed = not disabled and (modal or (not popup and not capture and not confirm))
    if allowed then
        focusItems[#focusItems + 1] = { id = id, fn = fn, adjust = adjust }
    end
    local over = allowed and hit(px, py, w, h, modal)
    -- Apply mouse actions after the drawing pass, so unload cannot allocate new objects mid-frame.
    if over and click then
        click = false
        keyboardMode = false
        focusId = id
        actionQueue[#actionQueue + 1] = fn
    end
    if allowed and focusId == id and keyboardMode then
        box(
            id .. "focus",
            px - 2,
            py - 2,
            w + 4,
            h + 4,
            accent,
            0.9,
            10,
            confirm and 88 or modal and 75 or 29
        )
        box(id .. "focusinner", px, py, w, h, tint, 1, 8, confirm and 89 or modal and 76 or 30)
    end
    return over
end

-- ===== media.lua =====
-- Existing anime media and permission-confirmed sprites; never generated artwork.
local artwork = {
    rias = {
        { Name = "Anime loop", Id = "rias" },
        { Name = "Opening frame", Id = "rias_still" },
        { Name = "Closing frame", Id = "rias_end" },
    },
    akeno = {
        { Name = "Golden evening", Id = "akeno" },
        { Name = "Quiet moment", Id = "akeno_evening" },
        { Name = "Blue sky", Id = "akeno_sky" },
        { Name = "Anime loop", Id = "akeno_motion" },
        { Name = "Opening frame", Id = "akeno_motion_still" },
        { Name = "Closing frame", Id = "akeno_motion_end" },
    },
}
app.RiasArtwork, app.AkenoArtwork = "Anime loop", "Golden evening"
app.RiasCompanion, app.AkenoCompanion = true, true
app.CompanionOrder, app.AnimatedMedia = "Rias first", true
local companionReaction = { rias = -100, akeno = -100 }
local function artworkId(character)
    local name = character == "rias" and app.RiasArtwork or app.AkenoArtwork
    for _, entry in ipairs(artwork[character] or {}) do
        if entry.Name == name then
            return entry.Id
        end
    end
    return character
end
function app:GetArtworkOptions(character)
    local result = {}
    for _, entry in ipairs(artwork[character] or {}) do
        result[#result + 1] = entry.Name
    end
    return result
end
function app:SetArtwork(character, name)
    for _, entry in ipairs(artwork[character] or {}) do
        if entry.Name == name then
            self[character == "rias" and "RiasArtwork" or "AkenoArtwork"] = name
            return true
        end
    end
    return false, "Unknown character artwork."
end
function app:SetRiasArtwork(value)
    return self:SetArtwork("rias", value)
end
function app:SetAkenoArtwork(value)
    return self:SetArtwork("akeno", value)
end
function app:SetCompanionEnabled(character, enabled)
    if not artwork[character] or type(enabled) ~= "boolean" then
        return false
    end
    self[character == "rias" and "RiasCompanion" or "AkenoCompanion"] = enabled
    return true
end
function app:SetRiasCompanion(value)
    return self:SetCompanionEnabled("rias", value)
end
function app:SetAkenoCompanion(value)
    return self:SetCompanionEnabled("akeno", value)
end
function app:SetCompanionOrder(value)
    if value ~= "Rias first" and value ~= "Akeno first" then
        return false
    end
    self.CompanionOrder = value
    return true
end
function app:SetAnimatedMedia(value)
    if type(value) ~= "boolean" then
        return false
    end
    self.AnimatedMedia = value
    return true
end
function app:ReactCompanion(character)
    if not artwork[character] then
        return false
    end
    companionReaction[character] = motionClock
    return true
end
local function renderCompanions()
    local order = app.CompanionOrder == "Rias first" and { "rias", "akeno" } or { "akeno", "rias" }
    local available = math.max(36, y / S - 5)
    local height = math.min(112, available)
    local slot = 0
    for _, character in ipairs(order) do
        if app[character == "rias" and "RiasCompanion" or "AkenoCompanion"] then
            local record = assetData[character .. "_pixel"]
            local width = height * record.Width / record.Height
            slot = slot + 1
            local px = W - 55 - (3 - slot) * (height * 0.85 + 8)
            local elapsed = motionClock - companionReaction[character]
            local jump = elapsed >= 0 and elapsed < 0.7 and math.sin(elapsed / 0.7 * math.pi) * 12 or 0
            local drift = math.sin(motionClock * 1.8 + slot) * 1.2
            if app.ReducedMotion or app.Quality == "Low" or not app.Effects then
                jump, drift = 0, 0
            end
            local py = math.max(-y / S + 2, -height - jump + drift + 2)
            local id = "companion_" .. character
            local over = interactive(id, px, py, width, height, function()
                app:ReactCompanion(character)
                app:Notify({
                    Title = character == "rias" and "Rias Gremory" or "Akeno Himejima",
                    Content = "Right here with you.",
                    Duration = 2,
                })
            end)
            bitmap(id, asset(character .. "_pixel"), px, py, width, height, 1, 0, 58)
            if over or elapsed < 0.7 then
                label(
                    id .. "name",
                    character == "rias" and "RIAS" or "AKENO",
                    px,
                    py + height + 3,
                    9,
                    accent,
                    1,
                    true,
                    59
                )
            end
        end
    end
end

-- ===== preferences.lua =====
-- Preferences are data only: configuration files never contain executable Lua.
do
    local CONFIG_FILE = "dxd-ui-v1.cfg"
    local MAX_CONFIG_BYTES = 8192
    local MAX_CONFIG_LINES = 96
    local audioAdapter = nil
    local audioBusy = false
    local pendingAudioCleanup = false
    local volumes = { master = 0.6, music = 0.55, sfx = 0.5 }
    local volumeOrder = { "master", "music", "sfx" }
    local qualityNames = { Low = true, Balanced = true, High = true }
    local defaults = {
        RiasArtwork = "Anime loop",
        AkenoArtwork = "Golden evening",
        RiasCompanion = true,
        AkenoCompanion = true,
        CompanionOrder = "Rias first",
        AnimatedMedia = true,
        Theme = "Gremory",
        Character = "rias",
        Quality = "Balanced",
        ReducedMotion = false,
        Effects = true,
        EffectStrength = 0.65,
        Keybind = 0xA1,
        Opacity = 0.97,
    }

    app.SettingsStatus = "Settings are stored only when you choose Save."
    app.AudioStatus = "No audio adapter connected."
    app.Audio = { playing = false, available = false, volume = volumes }

    local function boundedNumber(value, minimum, maximum)
        return type(value) == "number" and finite(value) and value >= minimum and value <= maximum
    end

    local function settingsResult(ok, message)
        app.SettingsStatus = message
        return ok, message
    end

    local function callAdapter(adapter, method, ...)
        if audioBusy then
            return false, "An audio operation is already in progress."
        end
        audioBusy = true
        local ok, result = pcall(adapter[method], adapter, ...)
        audioBusy = false
        if pendingAudioCleanup then
            pendingAudioCleanup = false
            app:_DestroyAudio()
        end
        if not ok or result == false then
            return false, "The audio adapter could not " .. method .. "."
        end
        return true
    end

    function app:SetQuality(value)
        if type(value) ~= "string" or not qualityNames[value] then
            return false, "Quality must be Low, Balanced, or High."
        end
        self.Quality = value
        return true
    end

    function app:SetReducedMotion(value)
        if type(value) ~= "boolean" then
            return false, "Reduced motion must be a boolean."
        end
        self.ReducedMotion = value
        return true
    end

    function app:SetEffects(value)
        if type(value) ~= "boolean" then
            return false, "Effects must be a boolean."
        end
        self.Effects = value
        return true
    end

    function app:SetEffectStrength(value)
        if not boundedNumber(value, 0, 1) then
            return false, "Effect strength must be a finite number from 0 to 1."
        end
        self.EffectStrength = value
        return true
    end

    function app:SetOpacity(value)
        if not boundedNumber(value, 0.7, 1) then
            return false, "Opacity must be a finite number from 0.7 to 1."
        end
        self.Opacity = value
        return true
    end

    function app:HasAudioAdapter()
        return audioAdapter ~= nil
    end

    function app:_DestroyAudio()
        if audioBusy then
            -- A provider can trigger the application's teardown from its callback.
            pendingAudioCleanup = true
            return true
        end
        local previous = audioAdapter
        audioAdapter = nil
        self.Audio.available = false
        self.Audio.playing = false
        self.AudioStatus = "No audio adapter connected."
        if not previous then
            return true
        end
        local paused = callAdapter(previous, "pause", 0.15)
        local disposed = true
        if type(previous.destroy) == "function" then
            disposed = callAdapter(previous, "destroy")
        end
        if not paused or not disposed then
            self.AudioStatus = "Audio adapter cleanup failed."
            return false, self.AudioStatus
        end
        return true
    end

    function app:SetAudioAdapter(adapter)
        if self.Alive == false and adapter ~= nil then
            return false, "The interface has been destroyed."
        end
        if audioBusy then
            return false, "An audio operation is already in progress."
        end
        if adapter == audioAdapter then
            return true
        end
        if adapter ~= nil then
            if type(adapter) ~= "table" then
                return false, "Audio adapter must be a table or nil."
            end
            for _, method in ipairs({ "play", "pause", "setVolume" }) do
                if type(adapter[method]) ~= "function" then
                    return false, "Audio adapter requires a " .. method .. " method."
                end
            end
            if adapter.destroy ~= nil and type(adapter.destroy) ~= "function" then
                return false, "Audio adapter destroy must be a function when supplied."
            end
        end
        local cleaned, cleanupError = self:_DestroyAudio()
        if not cleaned then
            return false, cleanupError
        end
        if adapter == nil then
            return true
        end
        -- Attach muted/paused; starting playback always requires an explicit call.
        -- Register first so teardown inside an initialization callback can dispose it.
        audioAdapter = adapter
        local paused = callAdapter(adapter, "pause", 0)
        if self.Alive == false or audioAdapter ~= adapter then
            return false, "Audio initialization was interrupted by cleanup."
        end
        if not paused then
            self:_DestroyAudio()
            self.AudioStatus = "Audio adapter could not initialize."
            return false, self.AudioStatus
        end
        for _, channel in ipairs(volumeOrder) do
            local ok = callAdapter(adapter, "setVolume", channel, volumes[channel], 0)
            if self.Alive == false or audioAdapter ~= adapter then
                return false, "Audio initialization was interrupted by cleanup."
            end
            if not ok then
                self:_DestroyAudio()
                self.AudioStatus = "Audio adapter could not initialize volumes."
                return false, self.AudioStatus
            end
        end
        self.Audio.available = true
        self.AudioStatus = "Audio ready."
        return true
    end

    function app:PlayAudio()
        if self.Alive == false then
            return false, "The interface has been destroyed."
        end
        if not audioAdapter then
            self.AudioStatus = "No audio adapter connected."
            return false, self.AudioStatus
        end
        local current = audioAdapter
        local ok, message = callAdapter(current, "play", 0.25)
        if self.Alive == false or audioAdapter ~= current then
            return false, "Audio playback was interrupted by cleanup."
        end
        if ok then
            self.Audio.playing = true
            self.AudioStatus = "Audio playing."
        else
            self.AudioStatus = message
        end
        return ok, self.AudioStatus
    end

    function app:PauseAudio()
        if self.Alive == false then
            return false, "The interface has been destroyed."
        end
        if not audioAdapter then
            self.AudioStatus = "No audio adapter connected."
            return false, self.AudioStatus
        end
        local current = audioAdapter
        local ok, message = callAdapter(current, "pause", 0.2)
        if self.Alive == false or audioAdapter ~= current then
            return false, "Audio playback was interrupted by cleanup."
        end
        if ok then
            self.Audio.playing = false
            self.AudioStatus = "Audio paused."
        else
            self.AudioStatus = message
        end
        return ok, self.AudioStatus
    end

    function app:SetVolume(channel, value)
        if self.Alive == false then
            return false, "The interface has been destroyed."
        end
        if audioBusy then
            return false, "An audio operation is already in progress."
        end
        if type(channel) ~= "string" or volumes[channel] == nil then
            return false, "Volume channel must be master, music, or sfx."
        end
        if not boundedNumber(value, 0, 1) then
            return false, "Volume must be a finite number from 0 to 1."
        end
        if audioAdapter then
            local current = audioAdapter
            local ok, message = callAdapter(current, "setVolume", channel, value, 0.15)
            if self.Alive == false or audioAdapter ~= current then
                return false, "Audio volume update was interrupted by cleanup."
            end
            if not ok then
                self.AudioStatus = message
                return false, message
            end
        end
        volumes[channel] = value
        return true
    end

    local function safeName(value)
        return type(value) == "string" and #value > 0 and #value <= 48 and value:match("^[%w _%-]+$") ~= nil
    end

    local function validKeybind(value)
        return boundedNumber(value, 8, 254) and value == math.floor(value) and value ~= 27
    end

    local settings = {
        { key = "riasArtwork", field = "RiasArtwork", method = "SetRiasArtwork", validate = safeName },
        { key = "akenoArtwork", field = "AkenoArtwork", method = "SetAkenoArtwork", validate = safeName },
        { key = "riasCompanion", field = "RiasCompanion", method = "SetRiasCompanion", kind = "boolean" },
        { key = "akenoCompanion", field = "AkenoCompanion", method = "SetAkenoCompanion", kind = "boolean" },
        {
            key = "companionOrder",
            field = "CompanionOrder",
            method = "SetCompanionOrder",
            validate = safeName,
        },
        { key = "animatedMedia", field = "AnimatedMedia", method = "SetAnimatedMedia", kind = "boolean" },
        -- Character selection applies its house theme; restore the user's theme after it.
        { key = "character", field = "Character", method = "SetCharacter", validate = safeName },
        { key = "theme", field = "Theme", method = "SetTheme", validate = safeName },
        {
            key = "quality",
            field = "Quality",
            method = "SetQuality",
            validate = function(value)
                return qualityNames[value] == true
            end,
        },
        { key = "reducedMotion", field = "ReducedMotion", method = "SetReducedMotion", kind = "boolean" },
        { key = "effects", field = "Effects", method = "SetEffects", kind = "boolean" },
        {
            key = "effectStrength",
            field = "EffectStrength",
            method = "SetEffectStrength",
            kind = "number",
            validate = function(value)
                return boundedNumber(value, 0, 1)
            end,
        },
        {
            key = "keybind",
            field = "Keybind",
            method = "SetKeybind",
            kind = "number",
            validate = validKeybind,
        },
        {
            key = "opacity",
            field = "Opacity",
            method = "SetOpacity",
            kind = "number",
            validate = function(value)
                return boundedNumber(value, 0.7, 1)
            end,
        },
    }
    local allowedKeys = { version = true, masterVolume = true, musicVolume = true, sfxVolume = true }
    for _, setting in ipairs(settings) do
        allowedKeys[setting.key] = true
    end

    local function convertValue(setting, value)
        if setting.kind == "boolean" then
            if value == "true" then
                return true, true
            elseif value == "false" then
                return true, false
            end
            return false
        elseif setting.kind == "number" then
            value = tonumber(value)
        end
        if setting.validate and not setting.validate(value) then
            return false
        end
        return true, value
    end

    function app:SaveSettings()
        if type(env.writefile) ~= "function" then
            return settingsResult(
                false,
                "This host cannot save files. Settings remain active for this session."
            )
        end
        local lines = { "version=1" }
        for _, setting in ipairs(settings) do
            local value = self[setting.field]
            local valid = convertValue(setting, tostring(value))
            if not valid then
                return settingsResult(
                    false,
                    "Could not save invalid " .. setting.key .. ". Use the settings API to update it."
                )
            end
            lines[#lines + 1] = setting.key .. "=" .. tostring(value)
        end
        for _, channel in ipairs(volumeOrder) do
            if not boundedNumber(volumes[channel], 0, 1) then
                return settingsResult(false, "Could not save invalid " .. channel .. " volume.")
            end
            lines[#lines + 1] = channel .. "Volume=" .. tostring(volumes[channel])
        end
        local ok, result = pcall(env.writefile, CONFIG_FILE, table.concat(lines, "\n") .. "\n")
        if not ok or result == false then
            return settingsResult(false, "Settings could not be written. Check your host's file permissions.")
        end
        return settingsResult(true, "Settings saved to " .. CONFIG_FILE .. ".")
    end

    function app:LoadSettings()
        if type(env.readfile) ~= "function" then
            return settingsResult(
                false,
                "This host cannot read settings files. Session settings are available."
            )
        end
        local ok, content = pcall(env.readfile, CONFIG_FILE)
        if not ok or type(content) ~= "string" then
            return settingsResult(false, "No readable saved settings found. Current settings are active.")
        end
        if #content > MAX_CONFIG_BYTES then
            return settingsResult(false, "Saved settings exceed the 8 KB limit. Current settings are active.")
        end
        local entries, duplicates = {}, {}
        local ignored, lineCount = 0, 0
        for line in (content .. "\n"):gmatch("([^\n]*)\n") do
            lineCount = lineCount + 1
            if lineCount > MAX_CONFIG_LINES then
                return settingsResult(
                    false,
                    "Saved settings contain too many lines. Current settings are active."
                )
            end
            line = line:gsub("\r$", "")
            if line:match("%S") and not line:match("^%s*#") then
                local key, value = line:match("^%s*([%a][%w]*)%s*=%s*(.-)%s*$")
                if not key or not allowedKeys[key] or #value > 64 then
                    ignored = ignored + 1
                elseif entries[key] ~= nil then
                    duplicates[key] = true
                    ignored = ignored + 1
                else
                    entries[key] = value
                end
            end
        end
        if entries.version ~= "1" or duplicates.version then
            return settingsResult(
                false,
                "Saved settings have an unsupported or missing version. Current settings are active."
            )
        end
        local applied = 0
        for _, setting in ipairs(settings) do
            local raw = entries[setting.key]
            if raw ~= nil and not duplicates[setting.key] then
                local valid, value = convertValue(setting, raw)
                local called, result = false, false
                if valid then
                    called, result = pcall(self[setting.method], self, value)
                end
                if called and result ~= false then
                    applied = applied + 1
                else
                    ignored = ignored + 1
                end
            end
        end
        for _, channel in ipairs(volumeOrder) do
            local key = channel .. "Volume"
            if entries[key] ~= nil and not duplicates[key] then
                local value = tonumber(entries[key])
                if boundedNumber(value, 0, 1) and self:SetVolume(channel, value) then
                    applied = applied + 1
                else
                    ignored = ignored + 1
                end
            end
        end
        local message = "Loaded " .. applied .. " saved settings."
        if ignored > 0 then
            message = message .. " Skipped " .. ignored .. " invalid or unknown entries."
        end
        return settingsResult(true, message)
    end

    function app:ResetSettings()
        local failed = 0
        for _, setting in ipairs(settings) do
            local ok, result = pcall(self[setting.method], self, defaults[setting.field])
            if not ok or result == false then
                failed = failed + 1
            end
        end
        local volumeDefaults = { master = 0.6, music = 0.55, sfx = 0.5 }
        for _, channel in ipairs(volumeOrder) do
            if not self:SetVolume(channel, volumeDefaults[channel]) then
                failed = failed + 1
            end
        end
        if failed > 0 then
            return settingsResult(
                false,
                "Some settings could not reset. Check the audio adapter before saving."
            )
        end
        return settingsResult(true, "Defaults restored for this session. Choose Save to keep them.")
    end
end

-- ===== components.lua =====
-- All coordinates are logical UI pixels. Compact mode reflows; it does not shrink text.
local function button(id, title, px, py, w, fn, primary, glyph, modal, disabled)
    local over = interactive(id, px, py, w, 38, fn, nil, modal, disabled)
    local hover = ease(id .. "hover", over and 1 or 0)
    local opacity = disabled and 0.35 or 1
    local layer = confirm and 90 or modal and 77 or 31
    box(id .. "rim", px, py, w, 38, primary and accent or ink, (primary and 0.8 or 0.12) * opacity, 8, layer)
    box(
        id .. "body",
        px + 1,
        py + 1,
        w - 2,
        36,
        primary and accent or mix(tint, white, 0.055 + hover * 0.04),
        (primary and 0.9 or 1) * opacity,
        7,
        layer + 1
    )
    label(id .. "text", title, px + 13, py + 11, 12, primary and tint or ink, opacity, true, layer + 4)
    if glyph then
        icon(id .. "glyph", glyph, px + w - 29, py + 9, primary and tint or accent, opacity, layer + 4)
    end
    return over
end
local function smallButton(id, glyph, px, py, fn, modal, disabled)
    local over = interactive(id, px, py, 34, 34, fn, nil, modal, disabled)
    box(
        id .. "body",
        px,
        py,
        34,
        34,
        ink,
        disabled and 0.025 or 0.045 + ease(id .. "hover", over and 0.06 or 0),
        8,
        modal and 77 or 32
    )
    icon(
        id .. "icon",
        glyph,
        px + 7,
        py + 7,
        disabled and muted or accent,
        disabled and 0.3 or 1,
        modal and 80 or 35
    )
end
local function sigil(id, cx, cy, r, opacity, z, tilt)
    local count = app.Quality == "Low" and 20 or app.Quality == "High" and 48 or 32
    local rotation = app.ReducedMotion and 0 or motionClock * 0.07
    for ring = 1, 2 do
        local radius = r * (ring == 1 and 1 or 0.82)
        for j = 1, count do
            local p = (j - 1) * math.pi * 2 / count + rotation
            local q = j * math.pi * 2 / count + rotation
            line(
                id .. ring .. "_" .. j,
                cx + math.cos(p) * radius,
                cy + math.sin(p) * radius * (tilt or 1),
                cx + math.cos(q) * radius,
                cy + math.sin(q) * radius * (tilt or 1),
                accent,
                opacity,
                z,
                1
            )
        end
    end
    for j = 1, 6 do
        local p = j * math.pi / 3 + rotation
        local q = p + math.pi * 2 / 3
        line(
            id .. "star" .. j,
            cx + math.cos(p) * r * 0.7,
            cy + math.sin(p) * r * 0.7 * (tilt or 1),
            cx + math.cos(q) * r * 0.7,
            cy + math.sin(q) * r * 0.7 * (tilt or 1),
            accent,
            opacity * 0.8,
            z,
            1
        )
    end
end
local function portrait(id, character, px, py, w, h, opacity)
    local bytes = asset(artworkId(character))
    local imageH = math.min(h, w * 224 / 400)
    local imageW = imageH * 400 / 224
    box(id .. "under", px, py, w, h, mix(tint, accent, 0.07), opacity, 12, 21)
    if not bitmap(id, bytes, px + (w - imageW) / 2, py, imageW, imageH, opacity, 12, 22) then
        sigil(id .. "fallback", px + w / 2, py + h * 0.45, math.min(w, h) * 0.28, 0.35 * opacity, 24)
        icon(id .. "crown", "crown", px + w / 2 - 10, py + h * 0.45 - 10, accent, opacity, 25, 0, 1.8)
        label(
            id .. "fallbackText",
            "Portrait unavailable",
            px + 18,
            py + h - 40,
            12,
            muted,
            opacity,
            false,
            25
        )
    end
end
local function currentCharacter()
    for _, c in ipairs(characters) do
        if c.Id == app.Character then
            return c
        end
    end
    return characters[1]
end
local function beginCapture()
    capture = { keys = {} }
    popup = nil
    focusId = nil
    for k = 8, 254 do
        capture.keys[k] = iskeypressed(k)
    end
end
local function numberText(n)
    return string.format("%.2f", n):gsub("%.?0+$", "")
end
local function renderControl(c, py, index)
    local id, px, width = c.Id, contentLeft, contentWidth
    local narrow = width < 470
    local rh = rowHeight - 10
    local enter = ease(
        id .. "appear",
        (app.ReducedMotion or motionClock - visitTime > (index - 1) * 0.035) and 1 or 0,
        16
    )
    local ca = contentA * enter * (c.Disabled and 0.45 or 1)
    py = py + (1 - enter) * 5
    local hover = ease(id .. "cardhover", hit(px, py, width, rh) and 1 or 0)
    box(id .. "rim", px, py, width, rh, ink, 0.09 * ca, 10, 22)
    box(id .. "card", px + 1, py + 1, width - 2, rh - 2, mix(tint, white, 0.035 + hover * 0.015), ca, 9, 23)
    local labelX = px + (narrow and 14 or 50)
    if not narrow then
        box(id .. "badge", px + 12, py + 15, 27, 27, accent, 0.07 * ca, 7, 24)
        icon(id .. "icon", c.Icon, px + 15.5, py + 18.5, accent, ca, 27, 0, 0.85)
    end
    local labelWidth = narrow and width - 28 or width - (c.Kind == "label" and 68 or 260)
    label(
        id .. "title",
        short(c.Title, math.max(12, math.floor(labelWidth / 7.1))),
        labelX,
        py + 13,
        13,
        ink,
        ca,
        true,
        27
    )
    label(
        id .. "description",
        short(c.Description, math.max(12, math.floor(labelWidth / 5.8))),
        labelX,
        py + 36,
        11,
        muted,
        ca,
        false,
        27
    )
    local rx = px + width - 190
    local ry = py + 17
    if narrow then
        rx = px + 14
        ry = py + 61
    end
    local rw = narrow and width - 28 or 174
    if c.Kind == "button" then
        button(id .. "action", c.ButtonText, rx, ry, rw, function()
            fire(c.Callback)
        end, false, "right", false, c.Disabled)
    elseif c.Kind == "toggle" then
        local bx = rx + rw - 47
        interactive(id .. "action", rx, ry, rw, 38, function()
            c:SetValue(not c.Value)
        end, nil, false, c.Disabled)
        local v = ease(id .. "switch", c.Value and 1 or 0)
        label(id .. "state", c.Value and "Enabled" or "Disabled", rx + 4, ry + 12, 11, muted, ca, false, 34)
        box(id .. "switch", bx, ry + 7, 44, 24, mix(muted, accent, v), (0.18 + v * 0.60) * ca, 12, 33)
        box(id .. "knob", bx + 4 + 20 * v, ry + 11, 16, 16, ink, ca, 8, 34)
    elseif c.Kind == "dropdown" then
        local function openDropdown()
            popup = { control = c, x = rx, y = math.min(ry + 42, H - 208), width = rw, offset = 0 }
            focusId = nil
            animations.dropdown = 0
        end
        interactive(id .. "action", rx, ry, rw, 38, openDropdown, function(direction)
            for i, v in ipairs(c.Options) do
                if v == c.Value then
                    c:SetValue(c.Options[clamp(i + direction, 1, #c.Options)])
                    break
                end
            end
        end, false, c.Disabled)
        box(id .. "select", rx, ry, rw, 38, ink, 0.055 * ca, 8, 32)
        label(
            id .. "value",
            short(c.Value, math.floor((rw - 43) / 6.4)),
            rx + 12,
            ry + 12,
            12,
            ink,
            ca,
            true,
            34
        )
        icon(id .. "arrow", "down", rx + rw - 28, ry + 9, accent, ca, 34)
    elseif c.Kind == "keybind" then
        button(
            id .. "action",
            capture and "Press a key..." or keyName(app.Keybind),
            rx,
            ry,
            rw,
            beginCapture,
            false,
            "key"
        )
    elseif c.Kind == "slider" then
        local sx, sw = rx + 3, rw - 6
        interactive(id .. "action", rx, ry, rw, 38, function()
            if not keyboardMode then
                slide = c
                c.SlideX = sx
                c.SlideWidth = sw
            end
        end, function(direction)
            c:SetValue(c.Value + direction * c.Step)
        end, false, c.Disabled)
        if slide == c and down and active and not popup and not capture and not c.Disabled then
            c:SetValue(c.Min + clamp((mx - x - sx * S) / (sw * S), 0, 1) * (c.Max - c.Min))
        end
        label(id .. "min", numberText(c.Min), sx, ry, 10, muted, ca, false, 34)
        label(id .. "value", numberText(c.Value), rx + rw - 47, ry, 12, accent, ca, true, 34)
        local v = ease(id .. "fill", (c.Value - c.Min) / (c.Max - c.Min))
        box(id .. "track", sx, ry + 27, sw, 3, ink, 0.15 * ca, 2, 33)
        box(id .. "fill", sx, ry + 27, sw * v, 3, accent, ca, 2, 34)
        box(id .. "thumb", sx + sw * v - 5, ry + 23, 11, 11, ink, ca, 6, 35)
    end
end
local function renderPopup()
    if not popup then
        return
    end
    local p = popup
    local c = p.control
    local reveal = ease("dropdown", 1, 24)
    local count = math.min(4, #c.Options - p.offset)
    local extra = #c.Options > 4 and 40 or 0
    local height = count * 35 + 12 + extra
    box("popshadow", p.x - 4, p.y + 4, p.width + 8, height + 6, black, 0.5 * reveal, 11, 68)
    box("poprim", p.x - 1, p.y - 1, p.width + 2, height + 2, accent, 0.5 * reveal, 9, 69)
    box("popup", p.x, p.y, p.width, height, mix(tint, white, 0.07), reveal, 8, 70)
    for j = 1, count do
        local value = c.Options[p.offset + j]
        local py = p.y + 6 + (j - 1) * 35
        local over = interactive("option" .. j, p.x + 4, py, p.width - 8, 33, function()
            c:SetValue(value)
            popup = nil
            focusId = c.Id .. "action"
        end, nil, true)
        local chosen = c.Value == value
        box(
            "optionbg" .. j,
            p.x + 4,
            py,
            p.width - 8,
            33,
            accent,
            (chosen and 0.17 or over and 0.10 or 0) * reveal,
            5,
            71
        )
        label(
            "optionvalue" .. j,
            short(value, math.floor((p.width - 40) / 6.2)),
            p.x + 11,
            py + 10,
            12,
            ink,
            reveal,
            chosen,
            74
        )
        if chosen then
            icon("optioncheck" .. j, "check", p.x + p.width - 28, py + 6, accent, reveal, 74)
        end
    end
    if extra > 0 then
        smallButton("optionprev", "left", p.x + p.width - 78, p.y + height - 38, function()
            p.offset = math.max(0, p.offset - 4)
        end, true, p.offset == 0)
        smallButton("optionnext", "right", p.x + p.width - 39, p.y + height - 38, function()
            p.offset = math.min(math.floor((#c.Options - 1) / 4) * 4, p.offset + 4)
        end, true, p.offset + 4 >= #c.Options)
    end
    if click and not hit(p.x, p.y, p.width, height, true) then
        popup = nil
        click = false
    end
end

